/**
 * A worked sequential design for the Verilog subset: an 8-bit accumulator CPU.
 *
 * Every construct here is the one a wider datapath uses — a bus register, a
 * ripple-carry ALU, a synchronous reset and an opcode mux chain — so the example
 * doubles as the syntax reference for the parser and as the reference design the
 * tests simulate and synthesize. The ISA is deliberately tiny:
 *
 *   op 00  ADD   acc <= acc + operand
 *   op 01  LOAD  acc <= operand
 *   op 10  AND   acc <= acc & operand
 *   op 11  XOR   acc <= acc ^ operand
 *
 * The clock is generated by the elaborator from the combinational depth, not by
 * a hard-coded period, so the functional run samples settled data. Real timing
 * still comes from the SKY130 STA pass after mapping.
 */
export const ACC_CPU_VERILOG = `// 8-bit accumulator CPU — ripple-carry ALU + synchronous-reset register
// op: 00 add, 01 load, 10 and, 11 xor. zero = acc == 0.
module acc_cpu(
  input clk,
  input rst,
  input [1:0] op,
  input [7:0] operand,
  output [7:0] acc,
  output zero
);
  reg [7:0] acc_r;
  wire [8:0] carry;
  wire [7:0] sum;

  assign sum[0] = acc_r[0] ^ operand[0];
  assign carry[1] = acc_r[0] & operand[0];
  assign sum[1] = acc_r[1] ^ operand[1] ^ carry[1];
  assign carry[2] = (acc_r[1] & operand[1]) | (carry[1] & (acc_r[1] ^ operand[1]));
  assign sum[2] = acc_r[2] ^ operand[2] ^ carry[2];
  assign carry[3] = (acc_r[2] & operand[2]) | (carry[2] & (acc_r[2] ^ operand[2]));
  assign sum[3] = acc_r[3] ^ operand[3] ^ carry[3];
  assign carry[4] = (acc_r[3] & operand[3]) | (carry[3] & (acc_r[3] ^ operand[3]));
  assign sum[4] = acc_r[4] ^ operand[4] ^ carry[4];
  assign carry[5] = (acc_r[4] & operand[4]) | (carry[4] & (acc_r[4] ^ operand[4]));
  assign sum[5] = acc_r[5] ^ operand[5] ^ carry[5];
  assign carry[6] = (acc_r[5] & operand[5]) | (carry[5] & (acc_r[5] ^ operand[5]));
  assign sum[6] = acc_r[6] ^ operand[6] ^ carry[6];
  assign carry[7] = (acc_r[6] & operand[6]) | (carry[6] & (acc_r[6] ^ operand[6]));
  assign sum[7] = acc_r[7] ^ operand[7] ^ carry[7];
  assign carry[8] = (acc_r[7] & operand[7]) | (carry[7] & (acc_r[7] ^ operand[7]));

  always @(posedge clk) begin
    if (rst) acc_r <= 8'b00000000;
    else case (op)
      2'b00: acc_r <= sum;
      2'b01: acc_r <= operand;
      2'b10: acc_r <= acc_r & operand;
      default: acc_r <= acc_r ^ operand;
    endcase
  end

  assign acc = acc_r;
  assign zero = ~|acc_r;
endmodule
`;

/** Bit array for a value, least-significant first, for testbench stimuli. */
export const cpuBits = (value: number, width: number): Array<0 | 1> =>
  Array.from({ length: width }, (_, index) => ((value >> index) & 1) as 0 | 1);
